    column_name,
    data_type,
    is_nullable
FROM information_schema.columns
WHERE table_name = 'customer'
  AND table_schema = 'public'
ORDER BY ordinal_position;

SELECT
    column_name,
    data_type,
    is_nullable
FROM information_schema.columns
WHERE table_name = 'customer'
  AND table_schema = 'public'
ORDER BY ordinal_position;

-- Q what is the total revenue generated by male vs female customers?
select gender,sum(purchase_amount) from customer
group by gender;

-- Q2: Which customers used a discount but still spent more than the average purchase_amount
select customer_id,purchase_amount
FROM customer
where discount_applied = 'yes' 
AND purchase_amount > (SELECT AVG(purchase_amount) FROM customer);



-- Q3:which are the top 5 products with the highest average rating

select * from (select *,dense_rank() over(order by avg_review desc) highest_avg_rate from 
(select  item_purchased,ROUND(avg(review_rating::NUMERIC),2) avg_review from customer
group by item_purchased) as t) as t1
where highest_avg_rate <=5;

-- Q4: Compare the average purchase amounts between standard and express shipping

select shipping_type,avg(purchase_amount) from customer
where shipping_type in ('Express','Standard')
group by shipping_type;


-- Q5: Do subscribed customers spend more? Compare average and total revenue 
-- between subscribers and non-subscribers
select 
    CASE WHEN subscription_status = 'Yes' THEN 'subscription'
     ELSE 'Non_subscription' END AS subscription_sts,
	 count(distinct customer_id),
	 avg(purchase_amount) avg_rev,sum(purchase_amount) total_revenue
	 from customer
GROUP BY subscription_sts;


-- Q6: Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased,
sum(case when discount_applied = 'yes' then 1 end),
count(customer_id) purchase_amount,
(sum(case when discount_applied = 'yes' then 1 end) * 100 / count(customer_id))  AS highest_per
from customer
GROUP BY item_purchased
ORDER BY highest_per DESC
LIMIT 5;
	   


-- Q7, Segment customers into New, Returning,and Loyal based on their total
-- number of previous purchases, and show the count of each segment

SELECT CASE WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases >= 2 and previous_purchases <= 10 then 'Returning'
			WHEN previous_purchases >= 11 THEN 'Loyal' END AS SEGMENT_CUSTOMERS,
			COUNT(DISTINCT customer_id) as count
from customer
GROUP BY SEGMENT_CUSTOMERS;

-- Q8. What are the top 3 most purchased products within each category?
select * from (select *,row_number() over(partition by category order by count desc) rn 
from (SELECT category,item_purchased, COUNT(distinct customer_id) as count
from customer
group by category,item_purchased) as t) as t1
WHERE rn <= 3
-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select subscription_status,count(distinct customer_id) as count from customer
where previous_purchases > 5 
group by subscription_status;



-- Q10. What is the revenue contribution of each age group?

select age_group,
sum(purchase_amount) revenue,
(select sum(purchase_amount) from customer) as total_revenue,
ROUND((sum(purchase_amount) * 100/(select sum(purchase_amount) from customer)),2) contribution 
from customer
group by age_group;


